package net.battlespades.bot;
import java.io.IOException;
import java.util.*;
import java.util.function.*;
import static net.battlespades.bot.BotState.*;
import net.battlespades.bot.BotState.Observer;
import static net.battlespades.bot.BotMessages.*;
/** Source in-process worker lifecycle/coalescing with an owner-confined decision controller. */
public final class BotWorker implements AutoCloseable {
    public interface Brain {void resetForMap(long epoch);void resetBot(int id,int generation);Intent decide(Perception frame);Map<String,Object> metrics();}
    @FunctionalInterface public interface Factory {Brain create(BotNavigationWorld world);}
    public record Status(boolean running,Integer processId,long restarts,long stalledRestarts,double intentSilenceSeconds,int queuedFrames,int queuedIntents,int pendingTerrainCells,long droppedFrames,long droppedIntents,boolean snapshotRequired,Long awaitingFrameId,long lastAcknowledgedFrameId,long lastHeartbeatBatchId,long lastHeartbeatFrameId,Long awaitingSnapshotTransferId,long snapshotRejections,long plannedRecycles,long crashRestarts){}
    private final Thread owner=Thread.currentThread();private final Object lock=new Object();private final Factory factory;private final DoubleSupplier clock;private final BiConsumer<String,Throwable> failure;private final double decisionHz,planningRate;
    private Thread thread;private volatile boolean stop;private MapSnapshot snapshot;private long serial,terrainEpoch=-1,terrainVersion=-1;private final LinkedHashMap<Observer,Perception> frames=new LinkedHashMap<>();private final LinkedHashMap<Cell,VoxelChange> pending=new LinkedHashMap<>(),overlay=new LinkedHashMap<>();private final ArrayDeque<Intent> intents=new ArrayDeque<>();private boolean running,ready;private long restarts,planned,crashes,rejections,droppedFrames,droppedIntents,lastAck=-1,lastBatch=-1;private Long awaiting;private double lastProcessed;private Map<String,Number> planningMetrics=Map.of();private Map<String,Object> behaviorMetrics=Map.of();
    public BotWorker(Factory factory,double decisionHz,double planningRate,DoubleSupplier clock,BiConsumer<String,Throwable> failure){this.factory=Objects.requireNonNull(factory);if(!Double.isFinite(decisionHz)||!Double.isFinite(planningRate))throw new IllegalArgumentException("Finite bot worker rates required");this.decisionHz=Math.max(1,decisionHz);this.planningRate=Math.max(1,planningRate);this.clock=Objects.requireNonNull(clock);this.failure=Objects.requireNonNull(failure);}
    /** Creates the production worker; the brain and all its mutable state are constructed on its thread. */
    public static BotWorker simple(double decisionHz,double planningRate,DoubleSupplier clock,BiConsumer<String,Throwable> failure){return new BotWorker(world->new SimpleBotBrain(world,decisionHz,clock),decisionHz,planningRate,clock,failure);}
    private void owned(){if(Thread.currentThread()!=owner)throw new IllegalStateException("Bot worker producer outside owner");}
    public void start(MapSnapshot map){owned();synchronized(lock){if(thread!=null&&thread.isAlive()){if(stop)throw new IllegalStateException("Previous bot worker is still stopping");publishMap(map);return;}snapshot=Objects.requireNonNull(map);serial++;terrainEpoch=map.mapEpoch();terrainVersion=map.topologyVersion();pending.clear();overlay.clear();for(var c:map.cells())overlay.put(c.coordinate(),c);frames.clear();intents.clear();running=true;ready=false;lastProcessed=clock.getAsDouble();stop=false;thread=Thread.ofPlatform().daemon().name("bot-navigation-worker").unstarted(this::run);thread.setUncaughtExceptionHandler((_,error)->report("bot worker fatal",error));thread.start();lock.notifyAll();}}
    public void publishMap(MapSnapshot map){owned();synchronized(lock){snapshot=Objects.requireNonNull(map);serial++;terrainEpoch=map.mapEpoch();terrainVersion=map.topologyVersion();pending.clear();overlay.clear();for(var c:map.cells())overlay.put(c.coordinate(),c);frames.clear();intents.clear();awaiting=null;ready=false;lock.notifyAll();}}
    public void discardTimeline(){owned();synchronized(lock){frames.clear();intents.clear();awaiting=null;}}
    public void restart(){owned();synchronized(lock){if(snapshot==null)return;serial++;frames.clear();intents.clear();awaiting=null;ready=false;restarts++;planned++;lock.notifyAll();}}
    public void publish(VoxelChange change,long epoch,long version){owned();synchronized(lock){if(epoch!=terrainEpoch)return;terrainVersion=Math.max(terrainVersion,version);pending.put(change.coordinate(),change);overlay.put(change.coordinate(),change);lock.notifyAll();}}
    public boolean snapshotRequired(){owned();synchronized(lock){return pending.size()>=65536;}}
    public boolean submit(Perception frame){owned();var key=new Observer(frame.observerId(),frame.observerGeneration());synchronized(lock){var previous=frames.get(key);if(previous!=null&&previous.frameId()>=frame.frameId()){droppedFrames++;return false;}if(previous==null&&frames.size()>=256){droppedFrames++;return false;}frames.put(key,frame);if(awaiting==null)awaiting=frame.frameId();lock.notifyAll();return true;}}
    public List<Intent> drain(int limit){owned();synchronized(lock){var result=new ArrayList<Intent>();for(int n=Math.min(Math.max(0,limit),intents.size());n>0;n--)result.add(intents.removeFirst());return List.copyOf(result);}}
    public Status status(){owned();synchronized(lock){boolean active=running&&ready&&thread!=null&&thread.isAlive();double silence=active&&awaiting!=null?Math.max(0,clock.getAsDouble()-lastProcessed):0;return new Status(active,null,restarts,0,silence,frames.size(),intents.size(),pending.size(),droppedFrames,droppedIntents,pending.size()>=65536,awaiting,lastAck,lastBatch,lastAck,null,rejections,planned,crashes);}}
    public Map<String,Number> planningMetrics(){owned();synchronized(lock){return planningMetrics;}}public Map<String,Object> behaviorMetrics(){owned();synchronized(lock){return behaviorMetrics;}}
    public boolean recoverIfStopped(){owned();MapSnapshot retained;synchronized(lock){if(stop||snapshot==null||thread==null||thread.isAlive())return false;retained=snapshot.rebase(terrainVersion,List.copyOf(overlay.values()));restarts++;crashes++;}start(retained);return true;}
    private record Batch(long serial,MapSnapshot snapshot,List<VoxelChange> changes,long epoch,long version,List<Perception> frames){}
    private Batch batch(long applied)throws InterruptedException{synchronized(lock){if(!stop&&snapshot!=null&&serial==applied&&pending.isEmpty()&&frames.isEmpty())lock.wait(250);if(stop)return null;MapSnapshot next=null;if(snapshot!=null&&serial!=applied){next=snapshot.rebase(terrainVersion,List.copyOf(overlay.values()));pending.clear();}var changes=List.copyOf(pending.values());pending.clear();var roster=new ArrayList<>(frames.values());roster.sort(Comparator.comparingLong(Perception::frameId));frames.clear();return new Batch(serial,next,changes,terrainEpoch,terrainVersion,List.copyOf(roster));}}
    private BotNavigationWorld world(){return new BotNavigationWorld(new PlanningBudget(planningRate,decisionHz),clock);}
    private void run(){BotNavigationWorld world=world();Brain brain=null;long applied=-1,batchId=0;int failures=0;try{brain=factory.create(world);while(!stop){Batch batch;try{batch=batch(applied);}catch(InterruptedException interrupted){if(stop)break;continue;}if(batch==null)break;try{
                if(batch.snapshot()!=null){try{world.load(batch.snapshot());}catch(RuntimeException invalid){report("bot map snapshot",invalid);world=world();brain=factory.create(world);applied=batch.serial();synchronized(lock){rejections++;ready=false;}continue;}brain=factory.create(world);brain.resetForMap(batch.snapshot().mapEpoch());applied=batch.serial();synchronized(lock){ready=true;}}
                else if(!batch.changes().isEmpty())world.apply(new WorldDelta(batch.epoch(),batch.version(),batch.changes()));
                var results=new ArrayList<Intent>();long processed=-1;refresh(world,batch.frames());for(var frame:batch.frames()){processed=Math.max(processed,frame.frameId());Intent intent=decide(world,brain,frame);if(intent!=null)results.add(intent);}failures=0;batchId++;var metrics=worldMetrics(world);var behavior=BotMessages.freeze(brain.metrics());double at=clock.getAsDouble();synchronized(lock){planningMetrics=metrics;behaviorMetrics=behavior;for(var intent:results){if(intents.size()>=128){intents.removeFirst();droppedIntents++;}intents.addLast(intent);}lastProcessed=at;lastBatch=batchId;lastAck=Math.max(lastAck,processed);if(awaiting!=null&&processed>=awaiting)awaiting=null;}
            }catch(RuntimeException fault){report("bot worker batch",fault);world=world();brain=factory.create(world);applied=-1;synchronized(lock){restarts++;crashes++;ready=false;failures++;long deadline=System.nanoTime()+(long)(Math.min(2,.25*failures)*1e9);while(!stop){long remaining=deadline-System.nanoTime();if(remaining<=0)break;try{java.util.concurrent.TimeUnit.NANOSECONDS.timedWait(lock,remaining);}catch(InterruptedException ignored){/* Only stop ends fault backoff early. */}}}}}
        }finally{synchronized(lock){running=ready=false;lock.notifyAll();}}}
    private void report(String label,Throwable error){try{failure.accept(label,error);}catch(RuntimeException reporting){if(reporting!=error)error.addSuppressed(reporting);}}
    private void refresh(BotNavigationWorld world,List<Perception> frames){if(frames.isEmpty())return;var live=new HashSet<Observer>();int roster=0;double latest=Double.NEGATIVE_INFINITY;for(var frame:frames){int bots=0;for(var p:frame.players()){if(p.bot())bots++;if(p.id()==frame.observerId()&&p.generation()==frame.observerGeneration()&&p.alive()&&p.spawned())live.add(new Observer(p.id(),p.generation()));}roster=Math.max(roster,bots);latest=Math.max(latest,frame.createdAt());}world.budget().scaleFor(Math.max(roster,live.size()));world.budget().refreshWaiters(live,latest);}
    private Map<String,Number> worldMetrics(BotNavigationWorld world){return world.budget().snapshot();}
    private Intent decide(BotNavigationWorld world,Brain brain,Perception frame){if(frame.mapEpoch()!=world.epoch()||frame.topologyVersion()>world.version())return null;if(frame.topologyVersion()!=world.version())frame=frame.withTopology(world.version());world.beginPlanning(new Observer(frame.observerId(),frame.observerGeneration()),frame.createdAt());boolean cancel=false;try{Intent intent=brain.decide(frame);cancel=intent!=null;return intent;}catch(RuntimeException fault){cancel=true;report("bot decision "+frame.observerId(),fault);brain.resetBot(frame.observerId(),frame.observerGeneration());return null;}finally{world.endPlanning(cancel);}}
    public void close(double timeoutSeconds)throws IOException{owned();if(!Double.isFinite(timeoutSeconds))throw new IllegalArgumentException("Finite shutdown timeout required");Thread current;synchronized(lock){stop=true;current=thread;lock.notifyAll();}if(current!=null){current.interrupt();try{current.join(java.time.Duration.ofNanos((long)(Math.max(0,timeoutSeconds)*1e9)));}catch(InterruptedException interrupted){Thread.currentThread().interrupt();throw new IOException("Bot worker shutdown interrupted",interrupted);}}synchronized(lock){if(current!=null&&current.isAlive())throw new IOException("Bot worker did not stop; retained owner thread prevents replacement");running=ready=false;snapshot=null;frames.clear();intents.clear();pending.clear();overlay.clear();thread=null;}}
    @Override public void close()throws IOException{close(3);}
}
